    "content": "<table><tr><th colspan=\"2\">ECONOMIC POLICY</th><th>Page</th></tr><tr><td colspan=\"2\">Moderate Growth Projected for U.S. Economy</td><td>3</td></tr><tr><th colspan=\"2\">TAX POLICY</th><td></td></tr><tr><td colspan=\"2\">Abstracts of Recent Taxation Studies</td><td>8</td></tr><tr><th colspan=\"2\">TREASURY ISSUES INDEX</th><td>9</td></tr><tr><th colspan=\"3\">FINANCIAL OPERATIONS</th></tr><tr><th colspan=\"3\">PROFILE OF THE ECONOMY</th></tr><tr><td colspan=\"2\">Growth of real gross national product</td><td>15</td></tr><tr><td colspan=\"2\">Federal deficit</td><td>15</td></tr><tr><td colspan=\"2\">Federal outlays and receipts as a share of gross national product</td><td>16</td></tr><tr><td colspan=\"2\">Personal saving</td><td>16</td></tr><tr><th colspan=\"3\">FEDERAL FISCAL OPERATIONS</th></tr><tr><td colspan=\"2\">Analysis.--Budget results for the third quarter, fiscal 1991</td><td>19</td></tr><tr><td colspan=\"2\">FFO-1.--Summary of fiscal operations</td><td>21</td></tr><tr><td colspan=\"2\">Chart.--Monthly receipts and outlays</td><td>22</td></tr><tr><td colspan=\"2\">FFO-2.--On-budget and off-budget receipts by source</td><td>23</td></tr><tr><td colspan=\"2\">Chart.--Budget receipts by source</td><td>25</td></tr><tr><td colspan=\"2\">FFO-3.--On-budget and off-budget outlays by agency</td><td>26</td></tr><tr><th colspan=\"3\">FEDERAL OBLIGATIONS</th></tr><tr><td colspan=\"2\">FO-1.--Gross obligations incurred within and outside the Federal Government by object class</td><td>28</td></tr><tr><td colspan=\"2\">FO-2.--Gross obligations incurred outside the Federal Government by department or agency</td><td>29</td></tr><tr><td colspan=\"2\">Chart.--Gross Federal obligations; gross Federal obligations incurred outside the Federal Government</td><td>31</td></tr><tr><th colspan=\"3\">ACCOUNT OF THE U.S. TREASURY</th></tr><tr><td colspan=\"2\">UST-1.--Elements of changes in Federal Reserve and tax and loan note account balances</td><td>32</td></tr><tr><th colspan=\"3\">FEDERAL DEBT</th></tr><tr><td colspan=\"2\">FD-1.--Summary of Federal debt</td><td>35</td></tr><tr><td colspan=\"2\">FD-2.--Interest-bearing public debt</td><td>35</td></tr><tr><td colspan=\"2\">FD-3.--Government account series</td><td>36</td></tr><tr><td colspan=\"2\">FD-4.--Interest-bearing securities issued by Government agencies</td><td>37</td></tr><tr><td colspan=\"2\">FD-5.--Maturity distribution and average length of marketable interest-bearing public debt held by private investors</td><td>38</td></tr><tr><td colspan=\"2\">FD-6.--Debt subject to statutory limitation</td><td>38</td></tr><tr><td colspan=\"2\">Chart.--Average length of the marketable debt</td><td>39</td></tr><tr><td colspan=\"2\">Chart.--Private holdings of Treasury marketable debt by maturity</td><td>40</td></tr><tr><td colspan=\"2\">FD-7.--Treasury holdings of securities issued by Government corporations and other agencies</td><td>41</td></tr><tr><th colspan=\"2\">TREASURY FINANCING OPERATIONS</th><td>42</td></tr></table>",
